===== lucifersdiary.com.conf =====
server {
    listen 80;
    listen [::]:80;
    server_name lucifersdiary.com www.lucifersdiary.com;

    # Allow ACME HTTP-01 challenge over HTTP (Let's Encrypt renewals)
    location ~ \.well-known {
        allow all;
        root /www/wwwroot/lucifersdiary.com;
    }

    # Everything else: force HTTPS
    location / {
        return 301 https://$host$request_uri;
    }
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name lucifersdiary.com www.lucifersdiary.com;

    ssl_certificate     /www/server/panel/vhost/cert/lucifersdiary.com/fullchain.pem;
    ssl_certificate_key /www/server/panel/vhost/cert/lucifersdiary.com/privkey.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_ciphers         HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers on;
    ssl_session_cache   shared:SSL:10m;
    ssl_session_timeout 1d;

    root /www/wwwroot/lucifersdiary.com;
    access_log /www/wwwlogs/lucifersdiary.com.log;
    error_log  /www/wwwlogs/lucifersdiary.com.error.log;

    location ~ /\.(?!well-known) {
        deny all;
    }

    location /api/ {
        proxy_pass http://127.0.0.1:3001;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection        "";
        proxy_buffering off;
        client_max_body_size 5M;
        proxy_read_timeout 120s;
    }

    location /admin {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade           $http_upgrade;
        proxy_set_header Connection        "upgrade";
        proxy_hide_header Cache-Control;
        proxy_hide_header Expires;
        add_header Cache-Control "no-store, no-cache, must-revalidate, max-age=0" always;
        add_header Pragma "no-cache" always;
        expires off;
    }

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade           $http_upgrade;
        proxy_set_header Connection        "upgrade";
    }
}

